import { For, Show } from 'solid-js';
import type { JSX } from 'solid-js';
import { RULE_KEY } from '../shared/chip.jsx';
import type { RuleKind } from '../shared/chip.jsx';
import { text } from '../../stores/view.js';
import { SlotIcon } from './strip.jsx';
import './edit.css';

export { GHOST_REVEAL_CLASS } from '../shared/edit-hook.jsx';

export type GhostOption = {
  label?: string;
  node?: JSX.Element;
  cls?: string;
  title?: string;
  on: boolean;
  action?: (e?: Event) => void;
};

function GhostButton(props: { option: GhostOption }): JSX.Element {
  const hasAction = () => typeof props.option.action === 'function';
  const silent = () => !props.option.on && !hasAction();
  const cls = () => ['ghost-option', props.option.node ? '' : 'ghost-text',
    props.option.cls || '',
    props.option.on ? '' : (hasAction() ? 'locked' : 'action-off')].filter(Boolean).join(' ');
  const explanation = () => props.option.title || props.option.label;
  return (
    <button
      type="button"
      class={cls()}
      title={explanation()}
      aria-label={explanation()}
      aria-disabled={silent() ? 'true' : undefined}
      on:click={(e: MouseEvent) => {
        if (silent() || !props.option.action) return;
        e.preventDefault();
        e.stopPropagation();
        props.option.action(e);
      }}
    >
      {props.option.node ?? props.option.label ?? ''}
      <Show when={!props.option.on && hasAction()}><SlotIcon /></Show>
    </button>
  );
}

export function GhostRow(props: { cls?: string; options: GhostOption[] }): JSX.Element {
  return (
    <div class={['ghost-row', props.cls || ''].filter(Boolean).join(' ')}>
      <For each={props.options.filter(Boolean)}>{(o) => <GhostButton option={o} />}</For>
    </div>
  );
}

export function GhostWithBox(props: {
  cls?: string; options: GhostOption[];
}): JSX.Element {
  return (
    <div class="ghost-wrap">
      <GhostRow cls={props.cls} options={props.options} />
    </div>
  );
}

export function GhostBadge(props: { kind: RuleKind; word?: string }): JSX.Element {
  return (
    <span class={`method ${props.kind} ghost-badge`}>
      {`+ ${props.word ?? text(RULE_KEY[props.kind])}`}
    </span>
  );
}

export function GhostChips(): JSX.Element {
  return (
    <span class="ghost-chips-header">
      <span class="ghost-plus" aria-hidden="true">+</span>
      <span class="c-chips">
        <span class="c-slot left ghost-slot">{text('edit.slotLeft')}</span>
        <span class="c-space"> </span>
        <span class="c-slot op ghost-slot">{text('edit.slotOperator')}</span>
        <span class="c-space"> </span>
        <span class="c-slot right ghost-slot">{text('edit.slotValue')}</span>
      </span>
    </span>
  );
}
