const OBLIGATION = `${ODRL}obligation`;

function runAndReveal(core: Core, fn: (f: unknown) => unknown): void {
  let fresh: unknown = null;
  void core.execute((f) => { fresh = fn(f); }, { group: true })
    .then((ok) => {
      const ref = termOf(fresh)?.value;
      if (!ok) return;
      // The choreography after a +: the section unfolds (jump opens every
      // <details> above the fresh card), and only then a soft movement — and
      // only if the card is not already standing in view. `center` and not
      // `start`, so the fresh card does not land against the top edge.
      if (ref) core.jump(ref, { smooth: true, block: 'center', ifNeeded: true });
      requestFocusOn(fresh);
    })
    .catch(() => {});
}

// `card` is the IRI of the card acted on, the same string the rule rows carry as
// their scope. Left out, the request lands on the first field that answers it.
export function requestFocusOn(fresh: unknown, card?: string | null): void {
  const t = termOf(fresh) as { id?: string; value?: string } | null;
  const address = focusAddress(t ?? fresh);
  if (address) requestEditFocus(address, card || '');
}

function cardClearQuads(core: Core, t0: unknown) {
  const g = core.graph();
  return (g && t0) ? core.edit.policyClearQuads(g, t0) : [];
}

export function CardHeaderStrip(props: { core: Core; ctx: CardHookCtx }): JSX.Element {
  const term = createMemo(() => termOf(props.ctx.pol));
  const derived = (): IconState => ({ on: false, title: text('edit.cardDerived') });
  const clearQuads = createMemo(() => cardClearQuads(props.core, term()));
  return (
    <Show
      when={term()}
      fallback={(
        <ActionStrip
          edit={props.ctx.titleEdit
            ? { on: false, title: text('edit.nameDerived') } : undefined}
          duplicate={derived()}
          remove={derived()}
        />
      )}
    >{(t0) => (
      <ActionStrip
        label={text('edit.stripLabel')}
        ref={(el) => zoneOnHeader(el, 'summary', DROPTARGET.CARD, t0())}
        edit={props.ctx.titleEdit as IconState | undefined}
        duplicate={props.ctx.pol.anon || !props.ctx.pol.iri
          ? { on: false, title: text('edit.duplicateNoIri') }
          : editState(props.core, {
            allow: props.core.editable(t0()),
            title: text('edit.duplicateHint'),
            action: () => runAndReveal(props.core,
              (f) => props.core.edit.duplicatePolicy(f, props.ctx.pol.iri)),
            term: t0(),
            unlockable: true,
          })}
        remove={editState(props.core, {
          allow: clearQuads().length > 0 && props.core.quadsInEditSource(clearQuads()),
          title: text('edit.removePolicy'),
          action: () => {
            void props.core.execute((f) => props.core.edit.removePolicy(f, t0()),
              { group: true })
              .then((ok) => { if (ok) showToast('edit.policyRemoved'); })
              .catch(() => {});
          },
          term: t0(),
          blocked: clearQuads(),
          unlockable: true,
        })}
      />
    )}</Show>
  );
}

const ATTACH_PRED: Record<string, string> = {
  permission: `${ODRL}permission`,
  prohibition: `${ODRL}prohibition`,
  duty: OBLIGATION,
};

export interface RuleCandidate {
  iri: string; curie: string | null; label: string; provenance: string[]; term?: unknown;
}

let ruleCache: {
  g: unknown; v: number; per: Record<string, RuleCandidate[]>;
} | null = null;

export interface RuleChoices {
  picks: RuleCandidate[];
  /** Nothing pickable BECAUSE it all hangs here already — a different sentence. */
  allLinked: boolean;
}

/** Every rule of this kind the graph would let us hang here. */
export function ruleChoices(core: Core, term: unknown, kind: string): RuleChoices {
  const g = core.graph();
  const v = graphVersion();
  if (!g || !term) return { picks: [], allLinked: false };
  if (!ruleCache || ruleCache.g !== g || ruleCache.v !== v) {
    ruleCache = { g, v, per: core.edit.ruleOptions(g) };
  }
  const pred = ATTACH_PRED[kind];
  const verdicts = (ruleCache.per[kind] || [])
    .filter((r) => promotable(core, r))
    .map((r) => ({ r, v: core.edit.attachCheck(g, term, pred, r.iri || r.term) }));
  const picks = verdicts.filter((x) => x.v.ok).map((x) => x.r);
  return {
    picks,
    allLinked: !picks.length && verdicts.some((x) => x.v.reason === 'alreadyLinked'),
  };
}

/** The link itself — the one reuse route, unchanged since the node-reuse round. */
function attachExisting(
  core: Core, term: unknown, kind: string, c: Candidate, card?: string | null,
): void {
  const pred = ATTACH_PRED[kind];
  const verdict = core.edit.attachCheck(core.graph(), term, pred, c.iri || c.term);
  if (!verdict.ok) {
    setRefusal(RULE_NOTICE[verdict.reason || ''] || 'edit.invalidIri', { input: c.label });
    return;
  }
  let fresh: unknown = null;
  void core.execute((f) => {
    // ONE GROUP: naming a nameless candidate and hanging it here are a single
    // act for the author, and so a single undo.
    const iri = c.iri || String(core.edit.promoteBlank(f, c.term).iri || '');
    if (iri) fresh = core.edit.attachRule(f, term, pred, iri).term;
  }, { group: true })
    .then((ok) => {
      if (!ok) return;
      showToast('edit.ruleAttached');
      closeReuse();
      // A reused rule is SHARED, so its address stands on more than one card:
      // the cursor belongs on the card the author picked it into.
      requestFocusOn(fresh, card);
    })
    .catch(() => {});
}

// The candidate list at the INSERTION PLACE of the section, opened by the ↻ in
// its heading. The two find each other through the shared key, not through a
// parent that owns both.
export function SectionReuse(props: { core: Core; ctx: SectionAddHookCtx }): JSX.Element {
  const term = createMemo(() => termOf(props.ctx.pol));
  return (
    <Show when={term()}>
      <SectionReuseList
        core={props.core}
        ctx={props.ctx}
        candidates={() => ruleChoices(props.core, term(), props.ctx.kind).picks}
        onPick={(c) => attachExisting(props.core, term(), props.ctx.kind, c,
          props.ctx.pol.iri)}
      />
    </Show>
  );
}

export function PlusIcon(): JSX.Element {
  return (
    <svg viewBox="0 0 16 16" width="13" height="13" aria-hidden="true">
      <path d="M7.25 2.5h1.5v4.75H13.5v1.5H8.75V13.5h-1.5V8.75H2.5v-1.5h4.75z" fill="currentColor" />
    </svg>
  );
}

// An arc open at the top right with an arrowhead on it: the ↻ of the reuse
// route as a drawing, so the heading keeps its own text content.
export function ReuseIcon(): JSX.Element {
  return (
    <svg viewBox="0 0 16 16" width="13" height="13" aria-hidden="true">
      <path
        d="M12.5 8a4.5 4.5 0 1 1-1.92-3.69"
        fill="none" stroke="currentColor" stroke-width="1.6"
      />
      <path d="M13.4 1.9 13.1 6 9.2 4.6z" fill="currentColor" />
    </svg>
  );
}

/** The 30x30 header box of a category heading, reused per rule section. */
export function SecIconButton(props: {
  cls: string; name: string; state: IconState; icon: JSX.Element;
}): JSX.Element {
  const locked = () => !props.state.on && !!props.state.action;
  return (
    <button
      type="button"
      class={props.cls + (props.state.on ? '' : (locked() ? ' locked' : ' action-off'))}
      title={props.state.title}
      aria-label={props.name}
      aria-disabled={props.state.on || locked() ? undefined : 'true'}
      onClick={(e) => {
        e.preventDefault();
        e.stopPropagation();
        props.state.action?.(e);
      }}
      onPointerDown={(e) => e.stopPropagation()}
    >
      {props.icon}
      <Show when={locked()}><SlotIcon /></Show>
    </button>
  );
}

const ADD_RULE: Record<string, {
  mut: (core: Core, f: unknown, t0: unknown) => unknown;
}> = {
  permission: { mut: (core, f, t0) => core.edit.addPermission(f, t0) },
  prohibition: { mut: (core, f, t0) => core.edit.addProhibition(f, t0) },
  duty: { mut: (core, f, t0) => core.edit.addDuty(f, t0, OBLIGATION) },
};

// The section heading carries the same two controls in all three kinds; the
// kind only travels as an argument, exactly as it does for the categories.
export function SectionAddButtons(props: {
  core: Core; ctx: SectionAddHookCtx;
}): JSX.Element {
  const term = createMemo(() => termOf(props.ctx.pol));
  const kind = () => props.ctx.kind as 'permission' | 'prohibition' | 'duty';
  const word = () => text(RULE_KEY[props.ctx.kind]);
  const addName = () => text('edit.addAria', { kind: word() });
  const addState = createMemo(() => {
    const t0 = term();
    return editState(props.core, {
      allow: props.core.editable(t0),
      title: addName(),
      action: () => {
        let fresh: unknown = null;
        void props.core.execute((f) => { fresh = ADD_RULE[kind()].mut(props.core, f, t0); },
          { group: true })
          .then((ok) => { if (ok) requestFocusOn(fresh); })
          .catch(() => {});
      },
      term: t0,
      unlockable: true,
    });
  });
  const useState = createMemo(() => {
    const choices = ruleChoices(props.core, term(), kind());
    return reuseState({
      core: props.core,
      term: term(),
      count: choices.picks.length,
      title: text('edit.reuse'),
      none: 'edit.reuseNone',
      allLinked: choices.allLinked,
      linked: 'edit.reuseAllLinked',
      toggle: () => toggleReuse(reuseKey(term()?.value || '', kind())),
    });
  });
  return (
    <Show when={term()}>
      <SecIconButton
        cls={`sec-add-btn card-${kind()}-plus sec-add-${kind()}`}
        name={addName()}
        state={addState()}
        icon={<PlusIcon />}
      />
      <SecIconButton
        cls={`sec-add-btn card-${kind()}-reuse sec-reuse-${kind()}`}
        name={text('edit.reuse')}
        state={useState()}
        icon={<ReuseIcon />}
      />
    </Show>
  );
}

const PURPOSE = `${ODRL}purpose`;

export function GroupRuleGhost(props: { core: Core; ctx: GroupHookCtx }): JSX.Element {
  const term = createMemo(() => termOf(props.ctx.pol));
  const kind = () => (props.ctx.kind === 'prohibition' ? 'prohibition' : 'permission');
  const prefillable = () => props.ctx.dimIri === PURPOSE && !!props.ctx.valueIri;
  const option = (): GhostOption => {
    const t0 = term();
    const value = props.ctx.valueLabel || props.ctx.valueIri || '';
    if (!prefillable()) {
      return {
        node: <GhostBadge kind={kind()} word={text(ADD_RULE_KEY[kind()])} />,
        cls: `group-${kind()}-plus`,
        title: text('edit.dimensionNoPrefill'),
        on: false,
      };
    }
    const state = editState(props.core, {
      allow: props.core.editable(t0),
      title: text('edit.addInDimension', { value }),
      action: () => {
        const opts = { purposeIri: props.ctx.valueIri as string };
        let fresh: unknown = null;
        void props.core.execute((f) => {
          fresh = kind() === 'prohibition'
            ? props.core.edit.addProhibition(f, t0, opts)
            : props.core.edit.addPermission(f, t0, opts);
        }, { group: true })
          .then((ok) => { if (ok) requestFocusOn(fresh); })
          .catch(() => {});
      },
      term: t0,
      unlockable: true,
    });
    return {
      node: <GhostBadge kind={kind()} word={text(ADD_RULE_KEY[kind()])} />,
      cls: `group-${kind()}-plus`,
      title: state.title,
      on: state.on,
      action: state.action,
    };
  };
  return (
    <Show when={term()}>
      <GhostWithBox cls="ghost-op-row" options={[option()]} />
    </Show>
  );
}

const ADD_WORD_KEY: Record<AddKind, string> = {
  offer: 'kind.offer',
  agreement: 'kind.agreement',
  request: 'kind.request',
  set: 'kind.set',
};

// The + of a section header: the same control in all four categories, so the
// kind only travels as an argument into the one minting flow.
export function NewPolicyGhost(props: { core: Core; ctx: AddHookCtx }): JSX.Element {
  const kind = (): AddKind => props.ctx.kind || 'offer';
  // The hover IS the name of an icon-only button, so it names this kind and no
  // other; title and aria-label say the same thing.
  const name = () => text('edit.addAria', { kind: text(ADD_WORD_KEY[kind()]) });
  const state = createMemo(() => editState(props.core, {
    allow: props.core.hasEditSource(),
    title: name(),
    // The fresh policy is blank, so the reveal travels as the TERM: a blank
    // node has no IRI to jump to, only its node id.
    action: () => runAndReveal(props.core,
      (f) => props.core.edit.createSkeleton(f, kind()).term),
    unlockable: true,
  }));
  return (
    <span class="new-policy">
      <SecIconButton
        cls={'new-policy-button sec-add-btn sec-add-' + kind()}
        name={name()}
        state={state()}
        icon={<PlusIcon />}
      />
    </span>
  );
}

