import { Show, createMemo } from 'solid-js';
import type { JSX } from 'solid-js';
import { targetPredicates } from '../../../model/parse.js';
import { text } from '../../../stores/view.js';
import type { Quad, Term } from '../../../model-boundary.js';
import { termOf } from './anchor.js';
import type { ReadStore } from './anchor.js';
import { fieldOptions } from '../card-field.jsx';
import { IriCombobox } from '../field.jsx';
import { Button } from '../button.jsx';
import { editState } from './state.jsx';
import type { Core } from './core.js';
import type { TargetHookCtx } from '../../shared/edit-hook.jsx';
import './slot-editor.css';

export function targetQuads(
  store: ReadStore | null, ruleTerm: Term | null, iri: string,
): Quad[] {
  if (!store || !ruleTerm || !iri) return [];
  const out: Quad[] = [];
  for (const pred of targetPredicates(store) as string[]) {
    out.push(...store.getQuads(ruleTerm, termOf(pred), termOf(iri), null));
  }
  return out;
}

export function TargetCross(props: { core: Core; ctx: TargetHookCtx }): JSX.Element {
  const ruleTerm = createMemo(() => termOf(props.ctx.rule));
  const quads = createMemo(() => targetQuads(
    props.core.graph(), ruleTerm(), props.ctx.iri || '',
  ));
  const state = () => editState(props.core, {
    allow: quads().length > 0 && props.core.quadsInEditSource(quads()),
    title: text('edit.removeTarget'),
    action: () => {
      void props.core.execute(
        (f) => props.core.edit.removeTarget(f, ruleTerm(), props.ctx.iri as string),
        { group: true },
      );
    },
    blocked: quads(),
    notApplicable: text('edit.removeNoLink'),
    unlockable: true,
  });
  return (
    <Show when={props.ctx.iri && ruleTerm()}>
      <span class="target-edit">
        <Button
          label="✕"
          cls={`target-x${state().on ? '' : (state().action ? ' locked' : ' action-off')}`}
          title={state().title}
          ariaLabel={state().title}
          onClick={(e) => state().action?.(e)}
        />
      </span>
    </Show>
  );
}

export function TargetGhost(props: { core: Core; ctx: TargetHookCtx }): JSX.Element {
  const ruleTerm = createMemo(() => termOf(props.ctx.rule));
  const options = createMemo(() => fieldOptions('targets'));
  const state = () => editState(props.core, {
    allow: props.core.editable(ruleTerm()),
    title: text('edit.addTarget'),
    term: ruleTerm(),
    unlockable: true,
  });
  return (
    <Show when={ruleTerm()}>
      <span class={`target-add${state().on ? '' : ' locked'}`}>
        <Show
          when={state().on}
          fallback={(
            <Button
              label={text('edit.addTarget')}
              cls={state().action ? 'locked' : 'action-off'}
              title={state().title}
              onClick={(e) => state().action?.(e)}
            />
          )}
        >
          <IriCombobox
            options={options()}
            placeholder={text('edit.addTarget')}
            ariaLabel={text('edit.addTarget')}
            onPick={(iri) => {
              if (!iri) return;
              void props.core.execute(
                (f) => props.core.edit.addTarget(f, ruleTerm(), iri),
                { group: true },
              );
            }}
          />
        </Show>
      </span>
    </Show>
  );
}
