// `stores/edit.ts` may never be imported statically: it drags the whole
// serialisation layer into the importer's chunk.
export type Core = typeof import('../../stores/edit.js');

let held: Core | null = null;

export async function attachCore(): Promise<Core> {
  if (!held) held = await import('../../stores/edit.js');
  return held;
}

export function core(): Core {
  if (!held) throw new Error('edit layer: the mutation core is not attached');
  return held;
}

export function _setCoreForTest(k: Core | null): void { held = k; }
